import em from '@$$emscript'
export const $U = em.$declare('COMPOSITE')

export function em$generate() {
    let out = $outfile('nrf.distro.54lxx/REGS.hpp')
    out.addFile('../nrf.54lxx/nrf.distro.54lxx/REGS.hpp.txt')
    out.close()
}

